(() => {
  const out = [], seen = new Set();
  const clock = /^\d{1,2}:\d{2}(?::\d{2})?$/, count = /^\d+(?:\.\d+)?[万亿wW]?$/;
  for (const card of document.querySelectorAll('[id^="waterfall_item_"]')) {
    const id = (/^waterfall_item_(\d{6,})$/.exec(card.id) || [])[1];
    if (!id || seen.has(id)) continue;
    const lines = (card.innerText || '').split('\n').map(x => x.trim()).filter(Boolean);
    let kind = 'video', duration = '', likes = '', author = '', published = '';
    if (lines[0] === '图文') { kind = 'note'; lines.shift(); }
    else if (clock.test(lines[0] || '')) duration = lines.shift();
    if (count.test(lines[0] || '')) likes = lines.shift();
    let end = lines.length;
    for (let i = lines.length - 1; i >= 0; i--) {
      if (/^·\s*/.test(lines[i])) { published = lines[i].replace(/^·\s*/, ''); end = i; break; }
    }
    if (end > 0 && lines[end - 1].startsWith('@') && lines[end - 1].length > 1) { author = lines[end - 1].slice(1).trim(); end -= 1; }
    else if (end > 1 && lines[end - 2] === '@') { author = lines[end - 1]; end -= 2; }
    const desc = lines.slice(0, end).join(' ').trim();
    if (!desc || !(author || published)) continue;
    seen.add(id);
    const meta = [author && '@' + author, published, likes && '赞 ' + likes, duration && '时长 ' + duration,
      kind === 'note' ? '图文' : '视频'].filter(Boolean).join(' · ');
    out.push({id, title: desc.slice(0, 200),
      snippet: (meta + (desc.length > 200 ? ' | ' + desc.slice(200, 1000) : '')).slice(0, 1200),
      url: 'https://www.douyin.com/' + (kind === 'note' ? 'note/' : 'video/') + id});
    if (out.length >= 30) break;
  }
  return out;
})()

(() => {
  const el = (k) => document.querySelector('[data-e2e="' + k + '"]');
  const lines = (node) => (node ? node.innerText || '' : '').split('\n').map(x => x.trim()).filter(Boolean);
  const num = (k) => { const t = lines(el(k)).join(''); return /^\d+(?:\.\d+)?[万亿wW]?$/.test(t) ? t : ''; };
  const kind = location.pathname.startsWith('/note/') ? 'note' : 'video';
  const ui = el('user-info');
  const uiText = lines(ui).join(' ');
  const author = (ui ? Array.from(ui.querySelectorAll('a[href*="/user/"]')).map(a => (a.innerText || '').trim().split('\n')[0].trim()).find(Boolean) : '') || '';
  const stats = /粉丝\s*([\d.]+[万亿wW]?)\s*获赞\s*([\d.]+[万亿wW]?)/.exec(uiText);
  const info = el('detail-video-info');
  let desc = lines(info && info.querySelector('h1')).join('\n');
  let published_at = lines(el('detail-video-publish-time')).join(' ').replace(/^发布时间[：:]?\s*/, '');
  let image_count = '';
  if (kind === 'note') {
    const note = lines(el('note-detail'));
    const at = note.findIndex(x => x.startsWith('发布时间'));
    let i = author ? note.indexOf(author) : -1;
    if (i >= 0) { i += 1; while (i < at && uiText.includes(note[i])) i++; }
    if (!desc && at >= 0 && i >= 0) desc = note.slice(i, at).join('\n');
    if (!published_at && at >= 0) published_at = note[at].replace(/^发布时间[：:]?\s*/, '');
    const pager = note.map(x => /^\d+\/(\d+)$/.exec(x)).find(Boolean);
    image_count = pager ? pager[1] : '';
  }
  const player = lines(el('player-container'));
  const mark = player.lastIndexOf('章节要点');
  const chapters = [];
  for (let i = mark + 1; mark >= 0 && i + 1 < player.length; i++) {
    if (/^\d{1,2}:\d{2}(?::\d{2})?$/.test(player[i]) && !/^\d{1,2}:\d{2}/.test(player[i + 1])) { chapters.push(player[i] + ' ' + player[i + 1]); i++; }
  }
  const top_comments = Array.from(document.querySelectorAll('[data-e2e="comment-item"]')).slice(0, 20)
    .map(c => lines(c).filter(x => !/^(\d+|分享|回复|\.\.\.|展开|收起)$/.test(x)).join(' ')
      .replace(/\s*\d*\s*分享\s*回复(?:\s*展开\d+条回复)?\s*$/, '')).filter(Boolean);
  const hashtags = Array.from(new Set(desc.match(/#[^\s#@]+/g) || [])).slice(0, 30);
  return {kind, author, author_stats: stats ? '粉丝 ' + stats[1] + ' · 获赞 ' + stats[2] : '',
    desc, published_at, image_count, likes: num('video-player-digg'), comments: num('feed-comment-icon'),
    collects: num('video-player-collect'), shares: num('video-player-share'), hashtags, chapters, top_comments};
})()
